import { directoryFor, newDocument } from "@gitspec/core/browser";
import { withBase, type ManifestSpace, type SiteManifest } from "@gitspec/render/browser";
import { $, escape } from "./ui.ts";

/**
 * Starting a document from the site.
 *
 * `gitspec new` serves an agent and a developer at a terminal. Someone who only ever
 * opens the published site had no way to begin one at all — which is most of the people
 * this surface exists for. The document it writes is generated by the same code the
 * command uses, so the two cannot produce different skeletons, and it arrives with its
 * navigation entry in one pull request (N-6).
 */
export function newScreen(args: {
    manifest: SiteManifest;
    onCreate: (space: ManifestSpace, title: string, kind: "spec" | "page") => Promise<void>;
}): void {
    const { manifest } = args;
    const spaces = manifest.spaces ?? [];

    const options = spaces
        .map((space) => `<option value="${escape(space.key)}">${escape(space.title)}</option>`)
        .join("");

    $("app").innerHTML = `
<div class="panel">
  <h1>Start a document</h1>
  <p class="note">
    GitSpec writes a document that already passes its own checks, works out where it
    belongs from where your other documents are, and adds it to the navigation — all in
    one pull request you review like any other change.
  </p>
  <label class="new-label" for="new-title">Title</label>
  <input id="new-title" placeholder="Caching strategy" autocomplete="off">
  <label class="new-label" for="new-kind">Kind</label>
  <select id="new-kind">
    <option value="spec">Spec — has required fields and is checked</option>
    <option value="page">Page — prose, checked against nothing</option>
  </select>
  ${spaces.length > 1 ? `<label class="new-label" for="new-space">Space</label><select id="new-space">${options}</select>` : ""}
  <p id="new-where" class="note"></p>
  <button id="new-create" class="primary">Create</button>
  <a class="note" href="${escape(withBase(manifest.base, "/"))}">Cancel</a>
</div>
<div id="result"></div>`;

    const title = $<HTMLInputElement>("new-title");
    const kindBox = $<HTMLSelectElement>("new-kind");
    const spaceOf = () =>
        spaces.find((s) => s.key === ($<HTMLSelectElement>("new-space")?.value ?? spaces[0]?.key)) ?? spaces[0];

    /**
     * Where the file will land, said before it is written.
     *
     * It also decides whether creating is allowed at all: G-4 refuses rather than
     * overwrites, and a button that opens a pull request replacing somebody's document
     * would be this screen breaking that promise on the command's behalf.
     */
    const preview = (): boolean => {
        const create = $<HTMLButtonElement>("new-create");
        const space = spaceOf();
        const text = title.value.trim();
        if (!space || !text) {
            $("new-where").textContent = "";
            create.disabled = true;
            return false;
        }
        const kind = kindBox.value === "page" ? "page" : "spec";
        const document = newDocument({
            title: text,
            kind,
            directory: directoryFor(
                kind,
                space.directory ?? space.path,
                manifest.documents.map((d) => ({ path: d.path, kind: d.kind })),
            ),
        });
        const clash = manifest.documents.find((d) => d.id === document.id || d.path === document.path);
        $("new-where").textContent = clash
            ? `${clash.path} already has that name — choose another title.`
            : `Will be written to ${document.path}`;
        $("new-where").classList.toggle("clash", Boolean(clash));
        create.disabled = Boolean(clash);
        return !clash;
    };

    title.addEventListener("input", preview);
    kindBox.addEventListener("change", preview);
    $<HTMLSelectElement>("new-space")?.addEventListener("change", preview);
    preview();

    $("new-create").addEventListener("click", async () => {
        const space = spaceOf();
        const text = title.value.trim();
        if (!space || !text || !preview()) return;
        const button = $<HTMLButtonElement>("new-create");
        button.disabled = true;
        button.textContent = "Creating…";
        try {
            await args.onCreate(space, text, kindBox.value === "page" ? "page" : "spec");
        } finally {
            button.disabled = false;
            button.textContent = "Create";
        }
    });

    title.focus();
}
